LOGOS = {52, 91, 171, 265}


def prepare(audit: Path, output: Path) -> dict:
    audit, output = audit.resolve(), output.resolve()
    output.mkdir(parents=True, exist_ok=True)
    rows = [json.loads(line) for line in (audit / "manifest.jsonl").read_text(encoding="utf-8").splitlines()]
    if len(rows) != 350 or {row["id"] for row in rows} != {f"IMG-{n:04d}" for n in range(1, 351)}:
        raise ValueError("Manual review applies only to this audited 350-image inventory")
    approved, review = [], []
    for original in rows:
        row = dict(original)
        # Ensure IDs still refer to the reviewed bytes, not a replaced input image.
        source = Path(row["path"])
        if hashlib.sha256(source.read_bytes()).hexdigest() != row["sha256"]:
            raise ValueError("Source changed after visual review: " + row["id"])
        number = int(row["id"][4:])
        selected = number in SELECTED
        row.update(
            visual_content_review="whole_vehicle_reference" if selected else "excluded_from_reference_subset",
            label_status="source_folder_label; canonical_model_not_verified",
            split="unassigned",
            suitable_for_real_world_acceptance=False,
        )
        if number in SWATCHES:
            row["exclusion_reason"] = "color_swatch_not_vehicle"
        elif number in LOGOS:
            row["exclusion_reason"] = "logo_or_text_card_not_vehicle"
        elif not selected:
            row["exclusion_reason"] = (
                "interior/detail/crop/overlay/multiple_vehicle_or_redundant_reference; excluded_by_visual_review"
            )
        if selected:
            destination = output / "images" / row["source_model"] / (row["id"] + ".jpg")
            destination.parent.mkdir(parents=True, exist_ok=True)
            with Image.open(source) as raw:
                im = ImageOps.exif_transpose(raw).convert("RGBA")
                im.thumbnail((1600, 1600))
                white = Image.new("RGBA", im.size, "white")
                white.alpha_composite(im)
                white.convert("RGB").save(destination, quality=95)
                row["prepared_width"], row["prepared_height"] = im.size
            row["prepared_image"] = destination.relative_to(output).as_posix()
            approved.append(row)
        review.append(row)
    summary = {
        "original_images": len(rows),
        "selected_references": len(approved),
        "excluded": len(rows) - len(approved),
        "by_source_model": dict(Counter(row["source_model"] for row in approved)),
        "color_swatches": len(SWATCHES),
        "logo_cards": len(LOGOS),
        "split": "unassigned",
        "status": "reference_content_cleaned; canonical_labels_and_near_duplicate_groups_pending",
        "source_modified": False,
        "limitations": [
            "Marketing/render reference images; no verified capture-group IDs or independent real-world test.",
            "Herio Green/VF5, Minio Green/VF2, VF8 variants etc require canonical taxonomy review, not automatic relabeling.",
            "542 dHash candidate pairs in full source inventory; similar structure is not proof of duplicate.",
            "No damage/no-damage ground truth or bbox labels in this dataset.",
        ],
    }
    for name, manifest in [("manifest.jsonl", approved), ("review-all.jsonl", review)]:
        (output / name).write_text(
            "".join(json.dumps(row, ensure_ascii=False) + "\n" for row in manifest), encoding="utf-8"
        )
    (output / "preparation-report.json").write_text(json.dumps(summary, ensure_ascii=False, indent=2), encoding="utf-8")
    print(json.dumps(summary, ensure_ascii=False, indent=2))
    return summary


if __name__ == "__main__":
    parser = argparse.ArgumentParser()
    parser.add_argument("--audit", type=Path, required=True)
    parser.add_argument("--output", type=Path, required=True)
    args = parser.parse_args()
    prepare(args.audit, args.output)
